(function(){
    var root=document.getElementById('sos-ajudinha'),toggle=document.getElementById('sos-ajudinha-toggle'),panel=document.getElementById('sos-ajudinha-panel'),closeButton=document.getElementById('sos-ajudinha-close'),motionButton=document.getElementById('sos-ajudinha-motion'),copy=document.getElementById('sos-ajudinha-copy');
    if(!root||!toggle||!panel||!closeButton||!motionButton||!copy)return;
    var media=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)'):null,reducedMotion=!!(media&&media.matches);
    function get(s,k){try{return s.getItem(k)}catch(e){return null}}function set(s,k,v){try{s.setItem(k,v)}catch(e){}}
    function paused(){return reducedMotion||get(window.localStorage,'sos-ajudinha-motion')==='paused'}
    function sync(){var p=paused();root.classList.toggle('is-paused',p);var animatedImages=root.querySelectorAll('[data-animated-src]');for(var i=0;i<animatedImages.length;i++){var image=animatedImages[i],source=p?image.getAttribute('data-static-src'):image.getAttribute('data-animated-src');if(source&&image.getAttribute('src')!==source)image.setAttribute('src',source)}motionButton.setAttribute('aria-pressed',String(p));motionButton.textContent=p&&!reducedMotion?'Ativar movimentos':'Pausar movimentos';motionButton.disabled=reducedMotion;if(reducedMotion)motionButton.textContent='Movimentos reduzidos pelo sistema'}
    function state(s){if(paused())return;root.setAttribute('data-state','idle');window.requestAnimationFrame(function(){window.requestAnimationFrame(function(){root.setAttribute('data-state',s||'attention')})})}
    function open(focus){panel.hidden=false;toggle.setAttribute('aria-expanded','true');state('greeting');if(focus)closeButton.focus()}
    function close(focus){panel.hidden=true;toggle.setAttribute('aria-expanded','false');root.setAttribute('data-state','idle');if(focus)toggle.focus()}
    var path=window.location.pathname.toLowerCase();if(path.indexOf('/calculos')!==-1)copy.textContent='Quer escolher um cálculo? Eu ajudo a encontrar a ferramenta certa.';else if(path.indexOf('/juros')!==-1)copy.textContent='Quer conferir a taxa do contrato? Compare com a média oficial do Banco Central.';else if(path.indexOf('/forum')!==-1)copy.textContent='Conte o que aconteceu, sem enviar documentos ou dados pessoais.';else if(path.indexOf('/jogo')!==-1)copy.textContent='Vamos aprender sobre dinheiro e direitos do consumidor de um jeito leve.';
    sync();window.setTimeout(function(){root.classList.add('is-ready')},80);toggle.addEventListener('click',function(){toggle.getAttribute('aria-expanded')==='true'?close(false):open(true)});closeButton.addEventListener('click',function(){close(true)});motionButton.addEventListener('click',function(){if(reducedMotion)return;var p=get(window.localStorage,'sos-ajudinha-motion')!=='paused';set(window.localStorage,'sos-ajudinha-motion',p?'paused':'active');sync();if(!p)state('success')});panel.addEventListener('click',function(e){var link=e.target.closest?e.target.closest('[data-ajudinha-action]'):null;if(link)state(link.getAttribute('data-ajudinha-action'))});root.addEventListener('animationend',function(e){if(e.animationName&&e.animationName.indexOf('ajudinha-')===0&&e.animationName!=='ajudinha-panel-in'&&e.animationName!=='ajudinha-idle')root.setAttribute('data-state','idle')});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!panel.hidden)close(true)});
    if(media){var changed=function(e){reducedMotion=!!e.matches;sync()};if(media.addEventListener)media.addEventListener('change',changed);else if(media.addListener)media.addListener(changed)}
    window.SOSAjudinha={open:function(){open(false)},close:function(){close(false)},setState:state};
})();
